"""Finite r012 oracle: stdlib only, no reader/scorer helpers, seed 12012.
Traversal ordered/exhaustive of selected valid transformations; no random fuzz.
"""
from pathlib import Path
import json,hashlib
R=Path.cwd();E=R/'temp/run-a002-fase1-corpus/evidence/implementation-r012'
TAIL='\n\n# Visible heading\n\nAfter words.'
URL='https://example.invalid';BAD='<img src="../outside.png">';SCRIPT='<script>x</script>';SAFE='<img src="p.png">'
HOSTS=['paragraph','quote','list','note-tab','note-spaces'];cases=[]
def transport(v,h):
 if h=='paragraph':return v
 if h=='quote':return '> '+v.replace('\n','\n> ')
 if h=='list':return '- '+v.replace('\n','\n    ')
 return '[^n]: '+v.replace('\n','\n'+('\t' if h=='note-tab' else '    '))
def add(name,value,host,kind,reason=None,detail=None,text=None,formula=None,visits=(),ref=False):
 raw=transport(value,host)+TAIL
 gold={'document_id':'r012-synthetic','blocks':[{'block_id':'p','type':'note' if host.startswith('note') else 'paragraph','text':text if text is not None else value,'page':1},{'block_id':'h','type':'heading','text':'Visible heading','page':1},{'block_id':'a','type':'paragraph','text':'After words.','page':1}]}
 if host.startswith('note'):gold['blocks'][0].update(note_id='n',anchor='n')
 if formula is not None:gold['blocks'][0]['formulas']=[{'formula_id':'f','reference_latex':formula,'symbols_expected':[],'structure_expected':None}]
 if ref:gold['blocks'][0]['references']=[{'kind':'link','text':'Known  words','target':URL}]
 pos={}
 for key,marker in [('formula','$'),('link','[Known'),('raw','`'),('unsafe','<script' if detail and 'script' in detail else '<img')]:
  at=raw.find(marker)
  if at>=0:pos[key]={'char':at,'byte':len(raw[:at].encode())}
 cases.append(dict(id=name,raw=raw,logical=value,host=host,kind=kind,reason=reason,detail=detail,text=text,formula=formula,ref=ref,visits=list(visits),positions=pos,gold=gold))
# Accepted LF ownership: escape, closed code, combination. Open math must
# expose real tags; closed math contains the literal HTML and remains opaque.
for h in HOSTS:
 for via in ['escape','code','combined']:
  for tag in [BAD,SCRIPT]:
   for closed in [True,False]:
    lf={'escape':'\\\ny','code':'`first\nsecond` y','combined':'`first\nsecond` \\\ny'}[via]
    payload='x '+tag+' '+lf
    formula=payload if closed else None
    value='È See [Known $'+payload+('$' if closed else '')+' words]('+URL+') end.'
    add('lf-'+h+'-'+via+'-'+str(tag==SCRIPT)+'-'+str(closed),value,h,'formula' if closed else 'unsafe',None if closed else 'UNSAFE_REFERENCE',None if closed else ('script' if tag==SCRIPT else '../outside.png'),text='È See Known  words end.' if closed else None,formula=formula,visits=[] if closed else ['script' if tag==SCRIPT else 'img'],ref=closed)
# Raw block in owning container, independent markers and closure. Normal
# fences are literal; safe raw body deliberately unprojected/unsupported.
for h in HOSTS[1:]:
 for marker in ['```','~~~']:
  for tag in [BAD,SCRIPT,SAFE]:
   for raw in [True,False]:
    for closed in [True,False]:
     value=marker+('{=html}' if raw else '')+'\n'+tag+('\n'+marker if closed else '')
     reason=('UNSAFE_REFERENCE' if tag!=SAFE else 'UNSUPPORTED_RESOURCE_SYNTAX') if raw else (None if closed else 'UNSUPPORTED_RESOURCE_SYNTAX')
     add('block-'+h+'-'+str(marker=='~~~')+'-'+str(tag==SCRIPT)+'-'+str(tag==SAFE)+'-'+str(raw)+'-'+str(closed),value,h,'block' if raw else 'literal-block',reason,'script' if raw and tag==SCRIPT else '../outside.png' if raw and tag==BAD else None,visits=['script' if tag==SCRIPT else 'img'] if raw else [])
# Raw inline / owner / order / LF transport, safe and unsafe first. Labels
# and outside label share exact format; ordinary code and latex are inert.
for h in HOSTS:
 for owner in ['markdown','html','closed-html']:
  for first in [SCRIPT,BAD,SAFE]:
   for second in [SCRIPT,BAD,'']:
    body='`'+first+'`{=html}' if owner=='markdown' else '<span>`'+first+'`</span>' if owner=='html' else '<span>safe</span> `'+first+'`'
    value='È See ['+body+']('+URL+') '+second
    real=first if owner!='closed-html' else second
    if real==SAFE:real=second
    detail='script' if real==SCRIPT else '../outside.png' if real==BAD else None
    reason='UNSAFE_REFERENCE' if detail else 'UNSUPPORTED_RESOURCE_SYNTAX' if owner=='markdown' else None
    visits=(['span'] if owner!='markdown' else [])+(['script' if first==SCRIPT else 'img'] if owner!='closed-html' else [])+(['script' if second==SCRIPT else 'img'] if second else [])
    add('owner-'+h+'-'+owner+'-'+str(first==SCRIPT)+'-'+str(first==SAFE)+'-'+str(second==SCRIPT)+'-'+str(second==''),value,h,'owner',reason,detail,visits=visits)
# Novel combinations: metadata after code containing LF, escaped LF before
# raw; source first unsafe remains stable after foreign close/tree error.
for h in HOSTS:
 for outside in [False,True]:
  for wrap in ['', '<span class="1" class="2">safe</span> ', '</em> ']:
   value='È See [Known \\\ny `<script>first\nlast</script>`{=html}]('+URL+')'+(' <img src="../second.png">' if outside else '')
   add('interaction-'+h+'-'+str(outside)+'-'+str(len(wrap)),wrap+value,h,'unsafe','UNSAFE_REFERENCE','script',visits=['script']+(['img'] if outside else []))
# Token barriers preserve unsupported, no false tag or borrowed math closure.
for h in HOSTS:
 for token in ['<!--\nsecret$ <script>x</script>\n-->','<![CDATA[\nsecret$ <img src="../outside.png">\n]]>']:
  add('token-'+h+'-'+str(token.startswith('<!--')),'È [Known $5 '+token+' words]('+URL+')',h,'token','UNSUPPORTED_RESOURCE_SYNTAX',visits=[])
# Free LF prevents a link; a closed standalone math remains lexical math.
for h in HOSTS:
 add('free-LF-'+h,'È [Known $x\ny$ words]('+URL+')',h,'free',None,formula='x\ny')
# Unsafe in a later physical block is visited after the first unsafe.
add('global-order',SCRIPT+'\n\n'+BAD,'paragraph','unsafe','UNSAFE_REFERENCE','script',visits=['script','img'])
value={'seed':12012,'method':'finite ordered selection, no random choice','limits':{'max_cases':400,'max_raw_bytes':2048},'oracle':'manual content/contracts, independent source coordinate offsets; no product imports','cases':cases}
assert len(cases)<=400 and len({c['id'] for c in cases})==len(cases)
assert max(len(c['raw'].encode()) for c in cases)<2048
p=E/'cases-before-002.json';p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n');print(len(cases),hashlib.sha256(p.read_bytes()).hexdigest())
